uint32_t __fastcall SKILLNEC_ValidateReviveTarget(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pCorpse) {
    if (!(pCorpse && pCorpse->eUnitType == UNIT_MONSTER)) {
      return 0;
    }

    int32_t nAlignment = D2Common::Stats::StatsEx::STATSEX_GetAlignment(pCorpse);
    if (nAlignment) {
      return 0;
    }

    uint32_t nCorpseCheck = UNIT::SUnit::UNITS_CheckIfCanAttackTarget(pGame, pUnit, pCorpse);
    if (!nCorpseCheck) {
      return 0;
    }

    BOOL bCheckResult = UNIT::SUnit::CheckForModeZeroDeath(pCorpse);
    if (bCheckResult) {
      return 0;
    }

    bCheckResult = SkillsServer::D2CheckCorpseConsumed(pCorpse, 0xb);
    return (uint32_t)(bCheckResult != 0);
}

